						encryptedPassword: "externalEncPassword",
					},
				],
			}

			migrateConfigV2to3(oldConfig)

			const expectedCredentialsAfterMigration: Array<Omit<PersistentCredentials, "databaseKey">> = [
				{
					credentialInfo: {
